"""Prisma Schema Generator for Agent 3.

Transforms extracted Mongoose schemas and relationships into
a valid PostgreSQL/Prisma schema (schema.prisma).
"""

from __future__ import annotations

from typing import Dict
from .models import ModelSchema


class SchemaGenerator:
    def __init__(self, schemas: Dict[str, ModelSchema]):
        self.schemas = schemas

    def generate(self) -> str:
        """Generate the complete schema.prisma string."""
        lines = [
            "// Generated by MigrateAI Migration Engineering Agent (Agent 3)",
            "",
            "datasource db {",
            '  provider = "postgresql"',
            '  url      = env("DATABASE_URL")',
            "}",
            "",
            "generator client {",
            '  provider = "prisma-client-js"',
            "}",
            "",
        ]

        # Analyze cross-model relations to properly define scalar foreign keys
        for model_name, model in self.schemas.items():
            lines.append(f"model {model_name} {{")
            lines.append("  id String @id @default(uuid())")

            # Check for relations referencing this model
            foreign_keys_to_add = []

            for field_name, field in model.fields.items():
                if field.field_type == "ObjectId" and field.relation_model:
                    target_model = field.relation_model
                    if field.is_list:
                        # 1-to-many from this side: posts Post[]
                        lines.append(f"  {field_name} {target_model}[]")
                    else:
                        # Many-to-1: authorId String?, author User? @relation(...)
                        fk_name = f"{field_name}Id"
                        optional = "" if field.is_required else "?"
                        lines.append(f"  {fk_name} String{optional}")
                        lines.append(
                            f"  {field_name} {target_model}{optional} @relation(fields: [{fk_name}], references: [id])"
                        )
                else:
                    ptype = self._map_primitive_type(field.field_type)
                    optional = "" if field.is_required else "?"
                    is_array = "[]" if field.is_list else ""
                    attrs = []
                    if field.is_unique:
                        attrs.append("@unique")
                    attr_str = f" {' '.join(attrs)}" if attrs else ""
                    lines.append(f"  {field_name} {ptype}{is_array}{optional}{attr_str}")

            if model.has_timestamps:
                lines.append("  createdAt DateTime @default(now())")
                lines.append("  updatedAt DateTime @updatedAt")

            lines.append("}")
            lines.append("")

        return "\n".join(lines).strip() + "\n"

    def _map_primitive_type(self, m_type: str) -> str:
        mapping = {
            "String": "String",
            "Int": "Int",
            "Number": "Int",
            "Float": "Float",
            "Boolean": "Boolean",
            "DateTime": "DateTime",
            "Date": "DateTime",
        }
        return mapping.get(m_type, "String")
